insert into public.products (slug,name,collection,tagline,description,price_cents,images,styles,stones,is_nfc,needs_size,featured,sort,owner_to_confirm) values
('tap-to-connect-bracelet','ConnecQ Tap-to-Connect Bracelet','tap-to-connect','Tiger eye and onyx with an NFC chip in the centerpiece.','A hand-strung stone bracelet with an NFC chip sealed into the centerpiece. Hold a phone to it and it opens the link you choose: your website, a music video, your socials or a Google review request. One link is programmed at a time. Water resistant and very flexible, sized to your wrist.',6500,array['/products/ttc-tiger-onyx-hex.webp','/products/ttc-tritone-jasper.webp','/products/ttc-onyx-worn.webp']::text[],'[{"key":"tiger-onyx","name":"Tiger eye & matte onyx, hex","image":"/products/ttc-tiger-onyx-hex.webp"},{"key":"tritone-jasper","name":"Tri-tone tiger eye, jasper oval","image":"/products/ttc-tritone-jasper.webp"},{"key":"onyx","name":"Polished onyx","image":"/products/ttc-onyx-worn.webp"}]'::jsonb,array['Tiger eye','Onyx','Picture jasper']::text[],true,true,true,10,'Price seen as $65 and $75 on Etsy. Confirm price and which stone styles are offered.'),
('custom-logo-tap-to-connect','Custom Logo Tap-to-Connect Bracelet','custom','Your logo on the charm, your link in the chip.','The Tap-to-Connect bracelet with your logo or photo sealed into the charm. The NFC chip opens the link you choose with one tap. After you order, send your logo to Anderberrybracelets@gmail.com and Amy and Aaron will confirm the design before it is made.',9999,array['/products/logo-charm-pk.webp','/products/logo-charm-agate.webp','/products/logo-charm-worn.webp']::text[],'[]'::jsonb,array['Tiger eye','Onyx','Agate','Hematite']::text[],true,true,true,20,'Price $99.99 from an Etsy snippet. Confirm.'),
('purple-and-gold-stack','Purple & Gold Tiger Eye Bracelet','gemstone','Purple tiger eye, honey tiger eye and gold hematite.','Purple and honey tiger eye with polished gold hematite, made for wearers who rep purple and gold. Shown with a custom charm; order it plain or ask for your chapter’s charm.',6500,array['/products/purple-gold-stack.webp']::text[],'[]'::jsonb,array['Purple tiger eye','Tiger eye','Hematite']::text[],false,true,true,30,'Based on the Etsy ''Omega Psi Phi Inspired'' listing ($65; an older snapshot showed $39.99). Confirm name, price, and whether Greek letters may be used.'),
('onyx-signet-bracelet','Onyx Signet Bracelet','gemstone','Polished onyx rounds around a square onyx signet.','Polished black onyx rounds with a square onyx centerpiece and matte hematite spacers. Hand-strung on stretch cord.',null,array['/products/onyx-square.webp','/products/onyx-tiger-in-hand.webp']::text[],'[]'::jsonb,array['Onyx','Hematite']::text[],false,true,false,40,'Name and price needed.'),
('tiger-eye-hex-bracelet','Tiger Eye Hex Bracelet','gemstone','Mixed tiger eye rounds with a cut hex centerpiece.','Golden, blue and red tiger eye rounds around a faceted tiger eye hex. Hand-strung on stretch cord.',null,array['/products/tiger-eye-hex.webp','/products/onyx-tiger-in-hand.webp']::text[],'[]'::jsonb,array['Tiger eye']::text[],false,true,false,50,'Name and price needed.'),
('logo-charm-bracelet','Logo Charm Bracelet','custom','Any logo, sealed in a charm, strung on the stones you pick.','For businesses, events, teams, chapters and families. Your logo is sealed under a clear dome on a round charm and strung with matte agate, onyx, hematite or tiger eye. Bulk orders welcome.',null,array['/products/logo-charm-agate.webp','/products/logo-charm-tcb.webp','/products/logo-charm-novelty.webp','/products/logo-charm-worn.webp']::text[],'[]'::jsonb,array['Agate','Onyx','Hematite','Tiger eye']::text[],false,true,true,60,'Price per piece and bulk pricing needed. Confirm permission to show the TCB 54 Hundred and MS Novelty logos.'),
('logo-gift-set','Logo Gift Set','custom','Bracelet, keychain and pin with your logo, boxed.','A matching bracelet, keychain and lapel pin carrying your logo, presented in a white gift box. Made for events, staff gifts and brand launches.',null,array['/products/gift-set-rnb.webp','/products/gift-set-legalshield.webp']::text[],'[]'::jsonb,array['Onyx','Red jasper','Amethyst']::text[],false,true,false,70,'Price needed. Confirm permission to show the R&B Versus Live and LegalShield logos.'),
('logo-lapel-pin','Logo Lapel Pin','pins','A domed logo pin with a clutch back. NFC chip optional.','Your logo under a clear dome on a pearl-finish disc with a gold clutch back. Add an NFC chip and the pin shares your contact card, socials, a document or a video with one tap.',null,array['/products/lapel-pin-coat.webp','/products/lapel-pin-front.webp','/products/lapel-pin-back.webp','/products/lapel-pin-side.webp']::text[],'[{"key":"standard","name":"Standard"},{"key":"nfc","name":"With NFC chip"}]'::jsonb,array[]::text[],true,false,false,80,'Price needed for standard and NFC versions.'),
('beaded-hat-pin','Beaded Hat Pin','pins','Stone, bone and wood beads on a steel pin.','A one-of-a-kind stacked bead pin for hats and lapels: carved bone, dzi-style glass, agate and wood on a steel stick pin with a capped end.',null,array['/products/hat-pin-dzi.webp','/products/hat-pin-agate.webp','/products/hat-pin-crackle.webp','/products/hat-pin-display.webp']::text[],'[{"key":"dzi","name":"Dzi eye","image":"/products/hat-pin-dzi.webp"},{"key":"agate","name":"Fire agate","image":"/products/hat-pin-agate.webp"},{"key":"crackle","name":"Bone crackle","image":"/products/hat-pin-crackle.webp"}]'::jsonb,array['Agate','Bone','Wood']::text[],false,false,false,90,'Price needed. Confirm these are still made.')
